const body = $json.body || $json;
const action = String(body.action || '').toLowerCase();
const suppliedSecret = String($json.headers?.['x-convertflow-admin-secret'] || $json.headers?.['X-Convertflow-Admin-Secret'] || '');
const secret = String($env.N8N_RENDER_CONTROL_SECRET || '');
const serviceId = String($env.RENDER_SERVICE_ID || '');
const apiKey = String($env.RENDER_API_KEY || '');

if (!secret || !serviceId || !apiKey) return [{ json: { success: false, message: 'Render control is not configured in n8n.' } }];
if (!suppliedSecret || suppliedSecret !== secret) return [{ json: { success: false, message: 'Unauthorized control request.' } }];
if (!['status', 'on', 'off'].includes(action)) return [{ json: { success: false, message: 'Invalid action.' } }];

const base = `https://api.render.com/v1/services/${serviceId}`;
let method = 'GET';
let url = base;
if (action === 'on') { method = 'POST'; url = `${base}/resume`; }
if (action === 'off') { method = 'POST'; url = `${base}/suspend`; }

try {
  const response = await this.helpers.httpRequest({ method, url, headers: { Authorization: `Bearer ${apiKey}`, Accept: 'application/json' }, returnFullResponse: true });
  let data = response.body;
  if (typeof data === 'string' && data.trim()) { try { data = JSON.parse(data); } catch {} }
  let status = 'unknown';
  if (action === 'off') status = 'suspended';
  else if (action === 'on') status = 'resuming';
  else {
    const serviceStatus = String(data?.suspended || data?.status || data?.service?.suspended || data?.service?.status || '').toLowerCase();
    status = serviceStatus.includes('suspend') ? 'suspended' : (serviceStatus || 'running');
  }
  return [{ json: { success: true, action, status, message: action === 'status' ? `Backend is ${status}.` : `Render ${action === 'on' ? 'resume' : 'suspend'} request accepted.`, renderStatusCode: response.statusCode } }];
} catch (error) {
  const statusCode = error.statusCode || error.response?.status || 502;
  return [{ json: { success: false, message: `Render API request failed with HTTP ${statusCode}.`, renderStatusCode: statusCode } }];
}
